import React,{createContext,useContext,useEffect,useState}from'react';
import{createRoot}from'react-dom/client';
import{supabase}from'./supabase-client.js';
import'./styles.css';
const AuthContext=createContext(null); let Students;
async function audit(action,entity_type,entity_id,details={}){try{const{data}=await supabase.auth.getUser();await supabase.from('audit_logs').insert({actor_id:data.user?.id||null,action,entity_type,entity_id,after_data:details})}catch(e){console.warn('audit log failed',e)}}
function printReceipt(payment){const w=window.open('','_blank','noopener,noreferrer');if(!w)return;w.document.write(`<html><head><title>Recibo Ikigai</title><style>body{font-family:Arial;padding:32px;color:#171513}h1{color:#b88a2c}hr{border:0;border-top:1px solid #ddd}p{font-size:16px}</style></head><body><h1>IKIGAI ACADEMY</h1><h2>Recibo de pago</h2><hr><p><b>Alumno:</b> ${payment.students?.full_name||'Alumno'}</p><p><b>Monto:</b> ₡${Number(payment.amount).toLocaleString('es-CR')}</p><p><b>Periodo:</b> ${payment.period}</p><p><b>Método:</b> ${payment.payment_method||'cash'}</p><p><b>Estado:</b> ${payment.status}</p><p><b>Fecha:</b> ${payment.paid_at?new Date(payment.paid_at).toLocaleString('es-CR'):'Pendiente'}</p><script>window.onload=()=>window.print()</script></body></html>`);w.document.close()}
const menu=[['calendar','Calendario','Vista mensual'],['schedule','Horarios','Días y horas'],['classes','Clases','Administrar clases'],['events','Eventos','Actividades especiales'],['programs','Programas','Disciplinas'],['levels','Niveles','Progresión'],['teachers','Profesores','Senseis'],['rooms','Salones','Espacios']];
function ClassForm(){const[days,setDays]=useState([]),toggle=d=>setDays(days.includes(d)?days.filter(x=>x!==d):[...days,d]);return <div className="class-form"><div className="form-grid"><label>Nombre de la clase<input placeholder="BJJ Adultos"/></label><label>Nivel<select><option>Principiante</option><option>Intermedio</option><option>Avanzado</option></select></label><label>Hora de inicio<input type="time" defaultValue="19:00"/></label><label>Duración<select><option>60 minutos</option><option>90 minutos</option><option>120 minutos</option></select></label><label>Profesor<select><option>Seleccionar profesor</option></select></label><label>Salón<select><option>Seleccionar salón</option></select></label><label>Capacidad<input type="number" min="1" placeholder="25"/></label><label>Edad mínima<input type="number" min="0" placeholder="16"/></label><label>Edad máxima<input type="number" min="0" placeholder="65"/></label><label>Recurrencia<select><option>Cada semana</option><option>Una sola vez</option><option>Personalizada</option></select></label></div><div className="days-field"><span>Días de la semana</span><div>{['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=><button type="button" key={d} className={days.includes(d)?'selected':''} onClick={()=>toggle(d)}>{d}</button>)}</div></div><label className="check-field"><input type="checkbox"/> Activar lista de espera</label><div className="form-actions"><button className="outline">Cancelar</button><button>Guardar clase</button></div></div>}
const eventTypes=['Seminario','Competencia','Examen de cinturones','Campamento','Torneo interno','Open mat'];
function Events(){return <div className="events-board"><div className="event-form"><label>Nombre del evento<input placeholder="Seminario de defensa"/></label><label>Tipo<select>{eventTypes.map(x=><option key={x}>{x}</option>)}</select></label><label>Fecha<input type="date"/></label><label>Precio<input type="number" placeholder="₡0"/></label><label>Cupos<input type="number" placeholder="50"/></label><label>Responsable<select><option>Seleccionar profesor</option></select></label></div><div className="event-stats">{[['0','Cupos'],['0','Asistentes'],['₡0','Pagos']].map(([n,l])=><div key={l}><strong>{n}</strong><span>{l}</span></div>)}</div><button>Guardar evento</button><div className="history-empty">No hay eventos registrados.</div></div>}
function WaitingList(){const[ask,setAsk]=useState(false);return <section className="waitlist-card"><div className="section-title"><div><p className="kicker">CONTROL DE CUPOS</p><h4>Lista de espera</h4></div><span className="capacity-chip">0 / 0</span></div><p className="waitlist-empty">La lista se activará automáticamente cuando una clase alcance su capacidad.</p><button className="outline" onClick={()=>setAsk(true)}>Simular cancelación</button>{ask&&<div className="cancel-prompt"><strong>¿Deseas asignar el espacio al siguiente alumno?</strong><p>No hay alumnos pendientes en la lista de espera.</p><button onClick={()=>setAsk(false)}>Cerrar</button></div>}</section>}
function Dashboard(){const today=new Intl.DateTimeFormat('es-CR',{weekday:'long',day:'numeric',month:'long'}).format(new Date()),[stats,setStats]=useState({students:0,income:0,overdue:0,classes:[]});useEffect(()=>{let live=true;(async()=>{const [st,pa,ov,cl]=await Promise.all([supabase.from('students').select('id',{count:'exact',head:true}).eq('active',true),supabase.from('payments').select('amount').eq('status','paid').gte('paid_at',new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString()),supabase.from('payments').select('id',{count:'exact',head:true}).eq('status','pending'),supabase.from('classes').select('id,name,start_time,capacity').eq('class_date',new Date().toISOString().slice(0,10)).order('start_time')]);if(live)setStats({students:st.count||0,income:(pa.data||[]).reduce((a,p)=>a+Number(p.amount||0),0),overdue:ov.count||0,classes:cl.data||[]})})().catch(()=>{});return()=>{live=false}},[]);return <><div className="dashboard-heading"><p className="kicker">PANEL DE ACADEMIA</p><h2>Buenos días, Sensei.</h2><p className="dashboard-date">{today.toUpperCase()}</p></div><div className="metric-grid"><div><strong>{stats.students}</strong><span>Alumnos</span></div><div><strong>₡{stats.income.toLocaleString('es-CR')}</strong><span>Ingresos del mes</span></div><div><strong>—</strong><span>Retención</span></div><div><strong>{stats.overdue}</strong><span>Pagos pendientes</span></div></div><div className="dashboard-grid"><section className="dashboard-card"><p className="kicker">AGENDA</p><h3>Clases de hoy</h3>{stats.classes.length?stats.classes.map(c=><div className="dashboard-empty" key={c.id}>{c.start_time?.slice(0,5)} · {c.name} · 0/{c.capacity||0}</div>):<div className="dashboard-empty">No hay clases registradas para hoy.</div>}</section><section className="dashboard-card"><p className="kicker">ATENCIÓN</p><h3>Requiere seguimiento</h3>{stats.overdue?<div className="dashboard-empty">Hay {stats.overdue} pagos pendientes por revisar.</div>:<div className="dashboard-empty">No hay alertas pendientes.</div>}</section></div></>}
function StudentApp(){return <div className="student-app"><div className="student-welcome"><div><p className="kicker">PORTAL DEL ALUMNO</p><h2>Hola 👋</h2><p>Tu camino en Ikigai, en un solo lugar.</p></div><div className="student-streak"><span>🔥 Racha</span><strong>0 días</strong></div></div><div className="student-app-grid"><section className="student-app-card"><p className="kicker">PRÓXIMAS CLASES</p><h3>Tu agenda</h3><div className="app-empty">No tienes clases reservadas.</div><button>Reservar una clase</button></section><section className="student-app-card"><p className="kicker">MI PROGRESO</p><h3>Camino marcial</h3><div className="app-stats"><span>🥋 Cinturón<small>Sin asignar</small></span><span>✅ Asistencia<small>0%</small></span><span>✦ Logros<small>0</small></span></div><button className="outline">Ver progreso</button></section><section className="student-app-card"><p className="kicker">MI CUENTA</p><h3>Acciones rápidas</h3><div className="app-actions"><button>💳 Pagar membresía</button><button>📣 Ver anuncios</button><button>🛍️ Comprar productos</button></div></section></div></div>}
function Notifications(){const items=[['📅','Próxima clase','Recordatorio de tu próxima sesión'],['💳','Pago pendiente','Tu membresía requiere atención'],['🥋','Nueva evaluación','Tu profesor registró una evaluación'],['🏆','Nuevo logro','Has desbloqueado un reconocimiento'],['🎂','Cumpleaños','Celebra a la comunidad Ikigai'],['📢','Anuncio','Novedades de la academia']];return <><div className="module-heading"><div><p className="kicker">CENTRO DE ACTIVIDAD</p><h2>Notificaciones</h2><p>Mantén informada a la comunidad Ikigai.</p></div><button>Marcar todo leído</button></div><section className="module-panel"><div className="notification-list">{items.map(([icon,title,help])=><div key={title}><span className="notification-icon">{icon}</span><div><strong>{title}</strong><small>{help}</small></div><b>Sin novedades</b></div>)}</div><div className="notification-note">Las notificaciones reales se generarán desde clases, pagos, evaluaciones, logros, cumpleaños y anuncios.</div></section></>}
function Insights(){const insights=[['⚠','Alumnos en riesgo','No hay suficientes datos de asistencia para detectar abandono.','Ver alumnos en riesgo'],['◒','Ocupación de clases','La ocupación se calculará con las reservas reales de cada horario.','Ver capacidad'],['💳','Vencimientos','Los recordatorios se activarán con membresías próximas a vencer.','Enviar recordatorio']];return <><div className="module-heading"><div><p className="kicker">MÓDULO INTELIGENTE</p><h2>IKIGAI Insights</h2><p>Recomendaciones accionables para dirigir mejor tu academia.</p></div><span className="insight-status">IA preparada</span></div><section className="module-panel"><div className="insights-list">{insights.map(([icon,title,text,action])=><article key={title}><span className="insight-icon">{icon}</span><div><p className="kicker">INSIGHT</p><h4>{title}</h4><p>{text}</p><button className="outline">{action}</button></div></article>)}</div><div className="insight-footer">Las recomendaciones se generarán a partir de alumnos, asistencia, clases, membresías y pagos reales.</div></section></>}
function Automations(){const[rules,setRules]=useState([['Membresía vence en 3 días','Enviar WhatsApp'],['Alumno falta 14 días','Crear tarea para recepción'],['Prospecto no responde 2 días','Enviar seguimiento']]);return <><div className="module-heading"><div><p className="kicker">MOTOR OPERATIVO</p><h2>Automatizaciones</h2><p>Convierte eventos repetitivos en acciones automáticas.</p></div><button>+ Nueva automatización</button></div><section className="module-panel"><div className="automation-list">{rules.map(([when,then],i)=><article key={when}><span className="automation-number">0{i+1}</span><div><p className="kicker">CUANDO</p><strong>{when}</strong><p className="kicker then-label">ENTONCES</p><strong>{then}</strong></div><button className="outline" onClick={()=>setRules(rules.filter((_,n)=>n!==i))}>Eliminar</button></article>)}</div><div className="automation-note">Las reglas se ejecutarán solo con datos reales y respetando los permisos del tenant.</div></section></>}
function AuthProvider({children}){const[session,setSession]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{let live=true;supabase.auth.getSession().then(({data})=>{if(live){setSession(data.session);setLoading(false)}});const{data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s));return()=>{live=false;subscription.unsubscribe()}},[]);return <AuthContext.Provider value={{session,loading,supabase}}>{children}</AuthContext.Provider>}
function Login(){const{supabase}=useContext(AuthContext),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');const{error}=await supabase.auth.signInWithPassword({email,password});if(error)setError(error.message);setBusy(false)}return <main className="auth"><div className="auth-card"><img src="/ikigai-logo.png"/><p className="kicker">ACADEMIA IKIGAI</p><h1>Tu camino empieza aquí.</h1><p>Inicia sesión para administrar las clases y la academia.</p><form onSubmit={submit}><label>Correo<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Contraseña<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="error">{error}</div>}<button disabled={busy}>{busy?'Entrando…':'Iniciar sesión'}</button></form></div></main>}
function Classes(){const[active,setActive]=useState('calendar'),item=menu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 01 · CLASES</p><h2>Clases y horarios</h2><p>Organiza la operación diaria de Ikigai desde un solo lugar.</p></div><button onClick={()=>setActive('classes')}>+ Nueva clase</button></div><div className="classes-layout"><nav className="subnav">{menu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[0]==='calendar'?'Calendario de clases':item[1]}</h3>{active==='classes'?<><ClassForm/><WaitingList/></>:active==='events'?<Events/>:<div className="empty-state"><div className="empty-mark">✦</div><strong>{item[0]==='calendar'?'Tu calendario empieza aquí':'Este apartado está listo para configurar'}</strong><p>Esta sección se conectará a Supabase con datos reales y permisos por rol.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div>}</section></div></>}
const studentMenu=[['all','Todos los alumnos','Directorio completo'],['new','Nuevos ingresos','Altas recientes'],['leads','Prospectos','Personas interesadas'],['trial','Clases de prueba','Seguimiento y conversión'],['families','Grupos / familias','Familias y grupos'],['minors','Menores','Portal para padres'],['inactive','Inactivos','Alumnos suspendidos'],['risk','Alumnos en riesgo','Detección premium'],['birthdays','Cumpleaños','Próximos cumpleaños'],['import','Importar alumnos','Carga masiva']];
const studentTabs=['Información','Membresía','Asistencia','Pagos','Progreso','Documentos'];
function StudentProfile(){const[tab,setTab]=useState('Información');return <section className="student-profile"><div className="profile-empty"><div className="profile-avatar">+</div><div><p className="kicker">PERFIL DEL ALUMNO</p><h3>Selecciona un alumno</h3><p>Elige un alumno del directorio para consultar su información, membresía, asistencia y progreso.</p></div></div><nav className="profile-tabs">{studentTabs.map(x=><button key={x} className={tab===x?'selected':''} onClick={()=>setTab(x)}>{x}</button>)}</nav><div className="profile-content"><p className="kicker">{tab.toUpperCase()}</p><h3>{tab}</h3><div className="profile-fields">{(tab==='Información'?['Nombre completo','Foto','Fecha de nacimiento','Teléfono','Email','Dirección','Contacto de emergencia','Estado','Fecha de ingreso']:tab==='Membresía'?['Plan actual','Fecha de inicio','Fecha de vencimiento','Precio','Descuento','Renovación automática','Congelaciones','Historial']:tab==='Asistencia'?['Resumen mensual','Clases disponibles','Asistencias','Ausencias','Última clase']:tab==='Pagos'?['Historial de pagos','Saldo pendiente','Último pago','Método de pago','Recibos']:tab==='Progreso'?['Nivel actual','Rango / cinturón','Evaluaciones','Técnicas','Metas','Logros','Competencias']:['Contrato','Waiver','Reglamento','Autorización','Documentos firmados']).map(x=><div key={x}><span>{x}</span><strong>Sin datos registrados</strong></div>)}</div></div></section>}
function RiskStudents(){return <div className="risk-board"><div className="risk-premium"><span>PREMIUM</span><strong>Detección temprana de abandono</strong><p>Identifica cambios de asistencia antes de perder la relación con el alumno.</p></div><div className="risk-card"><div className="risk-icon">⚠</div><div><p className="kicker">ALUMNOS EN RIESGO</p><h4>Sin alertas calculadas</h4><p>Necesitamos al menos dos períodos de asistencia para comparar la frecuencia de cada alumno.</p></div></div><div className="risk-rules"><p className="kicker">CÓMO FUNCIONA</p><div><span>01</span>Compara clases del período actual contra el anterior.</div><div><span>02</span>Detecta ausencias prolongadas y caídas de frecuencia.</div><div><span>03</span>Recomienda contactar al alumno.</div></div></div>}
const leadStages=['Nuevo','Contactado','Clase de prueba','Asistió','Oferta','Cliente'];
function Prospects(){const[stage,setStage]=useState('Nuevo');return <div className="crm-board"><div className="crm-toolbar"><div><p className="kicker">PIPELINE COMERCIAL</p><strong>Convierte consultas en alumnos</strong></div><button>+ Nuevo prospecto</button></div><div className="pipeline">{leadStages.map((x,i)=><button key={x} className={stage===x?'selected':''} onClick={()=>setStage(x)}><span>{i+1}</span>{x}</button>)}</div><div className="lead-empty"><div className="empty-mark">✦</div><h4>No hay prospectos en {stage.toLowerCase()}</h4><p>Las consultas de contacto y reservas de prueba aparecerán aquí.</p><button className="outline">Agregar prospecto</button></div><div className="lead-fields">{['Nombre','Origen','Interés','Estado'].map(x=><div key={x}><span>{x}</span><strong>Sin datos registrados</strong></div>)}</div></div>}
function TrialClasses(){const[converted,setConverted]=useState(null);return <div className="trial-board"><div className="trial-form"><p className="kicker">NUEVA CLASE DE PRUEBA</p><h4>Crear invitación</h4><div className="form-grid"><label>Prospecto<select><option>Seleccionar prospecto</option></select></label><label>Fecha<input type="date"/></label><label>Hora<input type="time"/></label><label>Ubicación<input placeholder="Tatami 1"/></label><label>Profesor<select><option>Seleccionar profesor</option></select></label><label>Instrucciones<input placeholder="Llegar 10 minutos antes"/></label></div><div className="trial-qr">▦<span>QR de acceso se generará al guardar</span></div><button>Guardar clase de prueba</button></div><div className="conversion-panel"><p className="kicker">SEGUIMIENTO</p><h4>¿Se convirtió?</h4><div className="conversion-actions"><button className={converted===true?'selected':''} onClick={()=>setConverted(true)}>Sí</button><button className={converted===false?'selected':''} onClick={()=>setConverted(false)}>No</button></div>{converted!==null&&<p className="conversion-result">Resultado registrado: {converted?'se convirtió en cliente':'no compró aún'}.</p>}</div><div className="trial-stats"><p className="kicker">ESTADÍSTICAS</p><div>{[['0','Pruebas'],['0','Asistieron'],['0','Compraron'],['0%','Conversión']].map(([n,l])=><div key={l}><strong>{n}</strong><span>{l}</span></div>)}</div></div></div>}
function Families(){const[show,setShow]=useState(false);return <div className="families-board"><div className="family-summary"><div className="family-avatar">♧</div><div><p className="kicker">CUENTA FAMILIAR</p><h4>Sin familias registradas</h4><p>Un tutor puede administrar pagos y varios alumnos desde una sola cuenta.</p></div></div><div className="family-actions"><button onClick={()=>setShow(!show)}>+ Nueva familia</button><button className="outline">Agregar integrante</button></div><div className="family-fields"><div><span>Pagador principal</span><strong>Sin datos registrados</strong></div><div><span>Cuenta</span><strong>Una cuenta compartida</strong></div><div><span>Integrantes</span><strong>0 alumnos</strong></div><div><span>Saldo familiar</span><strong>₡0</strong></div></div>{show&&<div className="new-plan-form"><input placeholder="Nombre del tutor / pagador"/><input placeholder="Correo de la cuenta"/><input placeholder="Teléfono"/><button>Guardar familia</button></div>}<div className="family-members"><p className="kicker">INTEGRANTES</p><div className="history-empty">Los alumnos vinculados a esta familia aparecerán aquí.</div></div></div>}
function Minors(){return <div className="minors-board"><div className="minor-callout"><span>👶</span><div><strong>Gestión segura de menores</strong><p>La información del menor se administra por medio de su tutor autorizado.</p></div></div><div className="minor-grid">{['Tutor responsable','Contactos de emergencia','Personas autorizadas para recoger','Autorizaciones','Documentos','Permisos','Comunicaciones'].map(x=><div key={x}><span>{x}</span><strong>Sin datos registrados</strong><button className="outline">Configurar</button></div>)}</div><div className="parent-portal"><p className="kicker">PORTAL PARA PADRES</p><h4>Acceso familiar</h4><p>El tutor podrá consultar clases, asistencia, pagos, avisos y autorizaciones desde su propia cuenta.</p><button>Configurar portal</button></div></div>}
const attendanceMenu=[['today','Hoy','Resumen del día'],['manual','Registro manual','Marcar asistencia'],['qr','QR','Acceso rápido'],['history','Historial','Registros anteriores'],['absences','Ausencias','Inasistencias'],['alerts','Alertas','Seguimiento']];
const membershipMenu=[['plans','Planes','Catálogo de planes'],['active','Membresías activas','Alumnos al día'],['expired','Vencidas','Renovaciones pendientes'],['frozen','Congeladas','Membresías pausadas'],['renewals','Renovaciones','Próximos vencimientos'],['promos','Promociones','Ofertas y beneficios']];
const planExamples=[['MMA BASIC','₡35.000'],['MMA FULL','₡50.000'],['MMA + BJJ','₡65.000'],['ILIMITADO','₡75.000']];
function Plans(){const[show,setShow]=useState(false);return <div className="plans-board"><div className="plans-grid">{planExamples.map(([name,price])=><article className="plan-card" key={name}><p className="kicker">PLAN</p><h4>{name}</h4><strong>{price}<small> / mes</small></strong><p>Configura disciplinas, clases y beneficios.</p><button className="outline">Editar plan</button></article>)}</div><div className="plan-features"><div className="section-title"><div><p className="kicker">CONFIGURACIÓN</p><h4>Características del plan</h4></div><button onClick={()=>setShow(!show)}>{show?'Ocultar':'+ Nuevo plan'}</button></div><div className="feature-grid">{['Periodicidad: mensual, trimestral, semestral o anual','Clases limitadas o ilimitadas','Múltiples disciplinas','Matrícula','Descuentos','Promociones','Renovación automática','Congelación de membresía'].map(x=><div key={x}>✓ {x}</div>)}</div>{show&&<div className="new-plan-form"><input placeholder="Nombre del plan"/><input type="number" placeholder="Precio"/><select><option>Mensual</option><option>Trimestral</option><option>Semestral</option><option>Anual</option></select><button>Guardar plan</button></div>}</div></div>}
function FreezeMembership(){const[from,setFrom]=useState(''),[to,setTo]=useState(''),[reason,setReason]=useState('');const days=from&&to?Math.max(0,Math.ceil((new Date(`${to}T12:00:00`)-new Date(`${from}T12:00:00`))/86400000)+1):0;return <div className="freeze-board"><div className="freeze-callout"><span>❄</span><div><strong>Congelar una membresía</strong><p>Pausa el cobro y extiende automáticamente el vencimiento por los días congelados.</p></div></div><label>Alumno<select><option>Seleccionar alumno</option></select></label><div className="freeze-form"><label>Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><label>Motivo<input value={reason} onChange={e=>setReason(e.target.value)} placeholder="Viaje"/></label></div><div className="freeze-summary"><span>Días a congelar <strong>{days}</strong></span><span>Nueva fecha de vencimiento <strong>{days?'Se calculará al guardar':'—'}</strong></span></div><button>Guardar congelación</button></div>}
function Renewals(){const[enabled,setEnabled]=useState(true);return <div className="renewals-board"><div className="game-toggle"><div><p className="kicker">AUTOMATIZACIÓN</p><strong>Alertas de renovación</strong><small>Da seguimiento a cada vencimiento a tiempo.</small></div><button className={enabled?'toggle-on':'toggle-off'} onClick={()=>setEnabled(!enabled)}>{enabled?'Activadas':'Desactivadas'}</button></div>{enabled&&<div className="renewal-rules">{[['5','La membresía vence en 5 días.','Recordatorio preventivo'],['1','La membresía vence mañana.','Último aviso'],['0','La membresía vence hoy.','Atención prioritaria'],['7+','Lleva 7 días con membresía vencida.','Seguimiento de morosidad']].map(([day,text,tag])=><div className="renewal-rule" key={day}><span className="renewal-day">{day}</span><div><strong>{text}</strong><small>{tag}</small></div><button className="outline">Configurar mensaje</button></div>)}<div className="history-empty">No hay membresías próximas a vencer con datos reales.</div></div>}</div>}
function ReferralProgram(){return <div className="referral-program"><div className="referral-summary"><div><strong>₡0</strong><span>créditos generados</span></div><div><strong>0</strong><span>referidos inscritos</span></div><button>+ Registrar referido</button></div><div className="referral-flow"><span>Alumno refiere</span><b>→</b><span>Nuevo alumno se inscribe</span><b>→</b><span>Crédito automático</span></div><div className="top-referrers"><p className="kicker">TOP REFERIDORES</p><div className="referrer-head"><span>Alumno</span><span>Referidos</span><span>Crédito</span></div><div className="history-empty">Aún no hay referidos registrados.</div></div></div>}
function Promotions(){const[show,setShow]=useState(false);return <div className="promos-board"><div className="promo-grid"><article className="promo-card"><p className="kicker">CUPÓN</p><h4>WELCOME20</h4><strong>20% descuento</strong><span>Primera mensualidad · Nuevos alumnos</span><button className="outline">Editar promoción</button></article><article className="promo-card referral"><p className="kicker">REFERIDOS</p><h4>Trae un amigo</h4><strong>10% para ambos</strong><span>El alumno y su referido reciben el beneficio.</span><button className="outline">Editar promoción</button></article></div><ReferralProgram/><div className="promo-config"><div className="section-title"><div><p className="kicker">PROMOCIONES</p><h4>Crear promoción</h4></div><button onClick={()=>setShow(!show)}>{show?'Cerrar':'+ Nueva promoción'}</button></div>{show&&<div className="new-plan-form"><input placeholder="Código del cupón"/><input type="number" placeholder="Descuento %"/><select><option>Primera mensualidad</option><option>Meses seleccionados</option><option>Plan específico</option></select><button>Guardar promoción</button></div>}</div></div>}
function Memberships(){const[active,setActive]=useState('plans'),item=membershipMenu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 04 · MEMBRESÍAS</p><h2>Membresías</h2><p>Administra planes, vencimientos y promociones de Ikigai.</p></div><button onClick={()=>setActive('plans')}>+ Nuevo plan</button></div><div className="classes-layout"><nav className="subnav">{membershipMenu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[1]}</h3>{active==='plans'?<Plans/>:active==='frozen'?<FreezeMembership/>:active==='renewals'?<Renewals/>:active==='promos'?<Promotions/>:<div className="empty-state"><div className="empty-mark">✦</div><strong>Esta vista está lista para configurar</strong><p>Conectaremos costos, estado, fechas de vencimiento y promociones a Supabase.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div>}</section></div></>}
const financeMenu=[['payments','Pagos','Cobros registrados'],['invoices','Facturas','Recibos y comprobantes'],['income','Ingresos','Entradas de dinero'],['expenses','Gastos','Costos de operación'],['cash','Cajas','Control de caja'],['overdue','Morosidad','Pagos pendientes'],['reports','Reportes','Resumen financiero']];
function PaymentsDashboard(){return <div className="payments-board"><div className="income-hero"><div><p className="kicker">INGRESOS ESTE MES</p><strong>₡0</strong><small>Sin pagos registrados</small></div><button>+ Registrar pago</button></div><div className="payment-bars"><div><span>Pagado</span><div className="payment-bar"><i style={{width:'0%'}}/></div><b>₡0</b></div><div><span>Pendiente</span><div className="payment-bar pending"><i style={{width:'0%'}}/></div><b>₡0</b></div></div><div className="payment-methods"><p className="kicker">MÉTODOS DE PAGO</p><div>{['Efectivo','Transferencia','Tarjeta','SINPE','Otros'].map(x=><button className="method-card" key={x}>{x}<small>₡0</small></button>)}</div></div><div className="gateway-note">Pasarela de pago <span>Próximamente</span><small>Podrás aceptar pagos en línea cuando conectemos el proveedor seleccionado.</small></div></div>}
function Overdue(){return <div className="overdue-board"><div className="overdue-summary"><strong>₡0</strong><span>pendiente de cobro</span><small>0 alumnos con pagos vencidos</small></div><div className="overdue-table"><div className="overdue-head"><span>Alumno</span><span>Monto</span><span>Atraso</span><span>Acciones</span></div><div className="history-empty">No hay pagos vencidos registrados.</div></div><p className="overdue-note">Los días de atraso se calcularán desde la fecha de vencimiento de cada membresía.</p></div>}
function Invoicing(){const[country,setCountry]=useState('Costa Rica');return <div className="invoicing-board"><div className="fiscal-selector"><label>País de operación<select value={country} onChange={e=>setCountry(e.target.value)}><option>Costa Rica</option><option>Guatemala</option><option>Panamá</option><option>Otro país</option></select></label><span>Adaptador fiscal: <strong>{country==='Costa Rica'?'Facturación electrónica':'Por configurar'}</strong></span></div><div className="invoice-flow">{['Pago','Factura','Proveedor fiscal','Comprobante','Cliente'].map((x,i)=><div key={x}><span>{i+1}</span><strong>{x}</strong>{i<4&&<b>→</b>}</div>)}</div><div className="fiscal-status"><p className="kicker">ESTADO FISCAL</p><h4>Integración pendiente</h4><p>La arquitectura separa pagos, facturas y proveedores para poder incorporar el comprobante fiscal oficial sin depender de un PDF.</p><button>Configurar proveedor</button></div><div className="history-empty">No hay facturas emitidas.</div></div>}
function Finance(){const[active,setActive]=useState('payments'),item=financeMenu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 05 · FINANZAS</p><h2>Finanzas</h2><p>Controla los ingresos, gastos y salud financiera de Ikigai.</p></div><button>+ Registrar pago</button></div><div className="classes-layout"><nav className="subnav">{financeMenu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[1]}</h3>{active==='payments'?<PaymentsDashboard/>:active==='overdue'?<Overdue/>:active==='invoices'?<Invoicing/>:<div className="empty-state"><div className="empty-mark">✦</div><strong>Esta vista está lista para configurar</strong><p>Los datos financieros se calcularán desde pagos y gastos reales en Supabase.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div>}</section></div></>}
