function EvaluationBoard(){const[student,setStudent]=useState(''),[note,setNote]=useState('');return <div className="evaluation-board"><div className="evaluation-toolbar"><label>Alumno<select value={student} onChange={e=>setStudent(e.target.value)}><option value="">Seleccionar alumno</option></select></label><label>Disciplina<select><option>BJJ</option><option>MMA</option><option>Karate</option><option>Judo</option></select></label><span className="status-chip">Borrador</span></div>{[['Técnica',8],['Defensa',7],['Condición',9],['Disciplina',10]].map(([item,score])=><div className="score-row" key={item}><span>{item}</span><div className="score-bar">{'█'.repeat(Math.round(score/1.25))}<i>{'░'.repeat(8-Math.round(score/1.25))}</i></div><b>{score}/10</b></div>)}<label className="note-field">Comentario del profesor<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Ej. Excelente evolución este mes." /></label><button>Guardar evaluación</button><div className="evaluation-history"><p className="kicker">HISTORIAL</p><h4>Evaluaciones anteriores</h4><div className="history-empty">No hay evaluaciones guardadas.</div></div></div>}
function TrainingPlan(){const[program,setProgram]=useState('Programa MMA'),[week,setWeek]=useState(1);const weeks={1:['Jab','Cross','Sprawl','Guard'],2:['Hooks','Takedown','Mount']};return <><div className="training-board"><div className="training-toolbar"><label>Programa<input value={program} onChange={e=>setProgram(e.target.value)}/></label><button>+ Nueva semana</button></div><div className="week-tabs">{Object.keys(weeks).map(x=><button className={week===Number(x)?'selected':''} onClick={()=>setWeek(Number(x))} key={x}>Semana {x}</button>)}</div><div className="technique-list">{weeks[week].map((x,i)=><div key={x}><span>{i+1}</span><strong>{x}</strong><small>Por enseñar</small><button className="outline">Marcar enseñada</button></div>)}</div><div className="training-note"><p className="kicker">SEGUIMIENTO DEL PROFESOR</p><span>El historial registrará qué técnica se enseñó, cuándo y a qué grupo.</span></div></div><TechniqueLibrary/></>}
