function TechniqueVideos(){const[show,setShow]=useState(false);return <div className="videos-board"><div className="video-upload"><div><p className="kicker">MATERIAL DIDÁCTICO</p><strong>Asocia videos a tus técnicas</strong><small>Los alumnos los revisarán desde su portal.</small></div><button onClick={()=>setShow(!show)}>+ Asociar video</button></div>{show&&<div className="video-form"><input placeholder="Nombre de la técnica, ej. Armbar desde guardia"/><input placeholder="URL del video"/><select><option>BJJ</option><option>MMA</option><option>Muay Thai</option><option>Karate</option></select><button>Guardar video</button></div>}<div className="video-empty"><div className="video-placeholder">▶</div><h4>No hay videos asociados</h4><p>Agrega una técnica y su video para crear tu biblioteca audiovisual.</p></div></div>}
function Certificates(){const[discipline,setDiscipline]=useState('BJJ'),[level,setLevel]=useState('Intermedio');return <div className="certificate-board"><div className="certificate-form"><label>Alumno<select><option>Seleccionar alumno</option></select></label><label>Disciplina<select value={discipline} onChange={e=>setDiscipline(e.target.value)}><option>BJJ</option><option>MMA</option><option>Karate</option><option>Judo</option></select></label><label>Nivel<select value={level} onChange={e=>setLevel(e.target.value)}><option>Principiante</option><option>Intermedio</option><option>Avanzado</option></select></label><button>Generar certificado</button></div><div className="certificate-preview"><p className="kicker">VISTA PREVIA</p><div className="certificate-paper"><span>IKIGAI ACADEMY</span><h4>CERTIFICADO</h4><p>Se certifica que</p><strong>Selecciona un alumno</strong><p>ha completado satisfactoriamente</p><b>Nivel {level} de {discipline}</b><small>IKIGAI Academy · {new Date().toLocaleDateString('es-CR')}</small></div><button className="outline">Descargar PDF</button></div></div>}
function Competitions(){const[event,setEvent]=useState({name:'',date:'',place:''});return <div className="competition-board"><div className="competition-section"><div className="section-title"><div><p className="kicker">EVENTOS</p><h4>Crear competencia</h4></div><button>+ Nuevo evento</button></div><div className="event-form"><label>Nombre<input value={event.name} onChange={e=>setEvent({...event,name:e.target.value})} placeholder="Copa Nacional BJJ"/></label><label>Fecha<input type="date" value={event.date} onChange={e=>setEvent({...event,date:e.target.value})}/></label><label>Lugar<input value={event.place} onChange={e=>setEvent({...event,place:e.target.value})} placeholder="San José"/></label></div></div><div className="competition-section"><div className="section-title"><div><p className="kicker">PARTICIPANTES</p><h4>Registro competitivo</h4></div><button className="outline">+ Agregar participante</button></div><div className="participant-grid">{['Alumno','Categoría','Peso','Edad','Cinturón','Resultado','Medalla','Victorias','Derrotas'].map(x=><div key={x}><span>{x}</span><strong>Sin registros</strong></div>)}</div></div><div className="competition-section"><p className="kicker">HISTORIAL</p><h4>Resumen por alumno</h4><div className="history-empty">No hay competencias registradas todavía.</div></div></div>}
