function POS(){const[query,setQuery]=useState('');return <div className="pos-board"><div className="pos-search"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar producto..."/><span>Carrito vacío</span></div><div className="pos-empty"><div className="empty-mark">✦</div><h4>Selecciona productos para iniciar una venta</h4><p>El POS registrará artículos, método de pago y recibo.</p><button>Configurar POS</button></div></div>}
