function Store(){const[active,setActive]=useState('products'),item=storeMenu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 08 · TIENDA</p><h2>Tienda</h2><p>Administra productos y ventas de Ikigai.</p></div><button onClick={()=>setActive('products')}>+ Nuevo producto</button></div><div className="classes-layout"><nav className="subnav">{storeMenu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[1]}</h3>{active==='products'?<ProductCatalog/>:active==='pos'?<POS/>:active==='inventory'?<Inventory/>:<div className="empty-state"><div className="empty-mark">✦</div><strong>Esta vista está lista para configurar</strong><p>Configura artículos, inventario y ventas desde un solo lugar.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div>}</section></div></>}
const staffMenu=[['teachers','Profesores','Perfiles y senseis'],['schedule','Horarios','Disponibilidad del equipo'],['commissions','Comisiones','Pagos y porcentajes'],['attendance','Asistencia','Registro del personal']];
function TeacherMetrics(){return <div className="teacher-board"><div className="teacher-profile"><div className="profile-avatar">+</div><div><p className="kicker">PERFIL DEL PROFESOR</p><h4>Sin profesores registrados</h4><p>Agrega instructores para consultar su rendimiento mensual.</p></div><button>+ Nuevo profesor</button></div><div className="teacher-metrics">{[['0','Clases este mes'],['0','Alumnos'],['0%','Asistencia promedio'],['0 h','Horas'],['₡0','Comisión']].map(([n,l])=><div key={l}><strong>{n}</strong><span>{l}</span></div>)}</div></div>}
function CommissionRules(){const[model,setModel]=useState('percentage');return <div className="commission-board"><div className="commission-callout"><p className="kicker">REGLAS DE PAGO</p><strong>Define cómo se calcula cada comisión.</strong><small>Las reglas se aplicarán a los profesores seleccionados.</small></div><label className="commission-label">Profesor<select><option>Seleccionar profesor</option></select></label><div className="commission-options">{[['percentage','Porcentaje de membresías'],['class','Monto por clase'],['student','Monto por alumno asistente']].map(([id,label])=><button key={id} className={model===id?'selected':''} onClick={()=>setModel(id)}>{label}</button>)}</div><div className="commission-input"><label>{model==='percentage'?'Porcentaje':'Monto'}<input type="number" placeholder="0"/><span>{model==='percentage'?'%':'₡'}</span></label></div><button>Guardar comisión</button></div>}
function Staff(){const[active,setActive]=useState('teachers'),item=staffMenu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 09 · PERSONAL</p><h2>Personal</h2><p>Organiza al equipo que hace crecer a Ikigai.</p></div><button>+ Nuevo profesor</button></div><div className="classes-layout"><nav className="subnav">{staffMenu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[1]}</h3>{active==='teachers'?<TeacherMetrics/>:active==='commissions'?<CommissionRules/>:<div className="empty-state"><div className="empty-mark">✦</div><strong>El equipo de Ikigai empieza aquí</strong><p>Configura profesores, horarios, comisiones y asistencia del personal.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div>}</section></div></>}
const reportGroups={Alumnos:['Nuevos','Activos','Inactivos','Abandonos','Crecimiento'],Asistencia:['Asistencia promedio','Clases más populares','Alumnos frecuentes','Alumnos ausentes'],Finanzas:['Ingresos','Gastos','Utilidad','Morosidad','Ingresos por plan'],Profesores:['Clases','Alumnos','Asistencia'],Ventas:['Productos','Ventas','Ticket promedio'],Analytics:['Retención','Churn','ARPU','LTV']};
function Reports(){const[group,setGroup]=useState('Alumnos');const months=['Enero','Febrero','Marzo','Abril','Mayo','Junio'];return <><div className="module-heading"><div><p className="kicker">MÓDULO 10 · REPORTES</p><h2>Reportes</h2><p>Convierte los datos de Ikigai en decisiones claras.</p></div><button>↗ Exportar reporte</button></div><section className="module-panel"><div className="report-tabs">{Object.keys(reportGroups).map(x=><button className={group===x?'selected':''} onClick={()=>setGroup(x)} key={x}>{x}</button>)}</div><p className="kicker">REPORTE DE {group.toUpperCase()}</p><h3>{group}</h3><div className="report-metrics">{reportGroups[group].map(x=><div key={x}><strong>0{group==='Analytics'&&x==='Churn'?'.0%':''}</strong><span>{x}</span><small>Sin datos registrados</small></div>)}</div>{group==='Analytics'&&<div className="analytics-months">{months.map(x=><div key={x}><span>{x}</span><strong>0</strong></div>)}</div>}<div className="report-chart"><div className="empty-mark">✦</div><strong>Gráfica disponible al conectar datos</strong><p>Este reporte se actualizará automáticamente desde la información real de Ikigai.</p></div></section></>}
const roles=['SUPER ADMIN','OWNER','ADMIN','MANAGER','INSTRUCTOR','RECEPTIONIST','ACCOUNTANT','STUDENT','PARENT'];
function TenantSecurity(){return <div className="tenant-security"><div className="security-header"><div><p className="kicker">SEGURIDAD SAAS</p><strong>Aislamiento por academia</strong><small>Cada consulta debe resolverse dentro del tenant autorizado.</small></div><span>RLS activo</span></div><div className="tenant-tree"><strong>Tenant: Ikigai Academy</strong><span>├── Usuarios</span><span>├── Alumnos</span><span>├── Clases</span><span>├── Pagos</span><span>├── Asistencia</span><span>└── Demás módulos</span></div><div className="security-checks">{['Todas las tablas incluyen tenant_id','Las consultas filtran por tenant autorizado','RLS bloquea acceso entre academias','Los roles limitan acciones dentro del tenant'].map(x=><div key={x}>✓ <span>{x}</span></div>)}</div></div>}
function IkigaiPlans(){const plans=[['Starter','$29/mes','100 alumnos','2 instructores','1 sucursal'],['Growth','$59/mes','500 alumnos','10 instructores','3 sucursales'],['Pro','$99/mes','∞ alumnos','∞ instructores','∞ sucursales']];return <div className="saas-plans"><p className="kicker">FACTURACIÓN IKIGAI</p><h3>Planes IKIGAI</h3><div className="saas-plan-grid">{plans.map(([name,price,students,teachers,branches])=><article key={name}><h4>{name}</h4><strong>{price}</strong><div>✓ {students}</div><div>✓ {teachers}</div><div>✓ {branches}</div><button className="outline">Seleccionar plan</button></article>)}</div></div>}
function SaaSBilling(){const features=['Suscripción activa','Renovación automática','Upgrade / downgrade','Cancelación','Período de gracia','Tarjeta de pago','Factura','Historial de cobros','Bloqueo por impago'];return <div className="saas-billing"><div className="billing-status"><p className="kicker">SUSCRIPCIÓN IKIGAI</p><strong>Sin plan seleccionado</strong><span>Configura un plan para activar el billing.</span><button>Configurar suscripción</button></div><div className="billing-features">{features.map(x=><div key={x}><span>✓</span><strong>{x}</strong><small>Preparado</small></div>)}</div></div>}
function TasksAudit(){const[tasks,setTasks]=useState(['Llamar a un alumno','Cobrar membresía pendiente','Confirmar clase de prueba','Renovar membresía']);const[done,setDone]=useState([]);return <div className="tasks-audit"><div className="tasks-panel"><p className="kicker">RECEPCIÓN</p><h4>Tareas</h4>{tasks.map(x=><label key={x} className={done.includes(x)?'task-done':''}><input type="checkbox" checked={done.includes(x)} onChange={()=>setDone(done.includes(x)?done.filter(y=>y!==x):[...done,x])}/>{x}</label>)}<button className="outline">+ Nueva tarea</button></div><div className="audit-panel"><p className="kicker">TRAZABILIDAD</p><h4>Auditoría</h4><div className="history-empty">No hay acciones administrativas registradas.</div><small>Cada cambio guardará quién eliminó, modificó, cobró, descontó o congeló.</small></div></div>}
function AcademyConfig(){return <div className="academy-config"><p className="kicker">WHITE LABEL · ACADEMIA</p><h3>Identidad y preferencias</h3><div className="config-grid">{['Nombre','Logo','Colores','Moneda','Zona horaria','País','Impuestos','WhatsApp','Email','Disciplinas','Niveles','Métodos de pago','Políticas'].map(x=><label key={x}>{x}<input placeholder="Configurar"/></label>)}</div><button>Guardar configuración</button><p className="config-note">Tu academia, tu marca, un solo sistema. El dominio personalizado se configurará al publicar.</p></div>}
function RoleModes(){const[mode,setMode]=useState('Instructor');const modes={Instructor:['Hoy · 19:00 BJJ · 0 alumnos','Iniciar clase','Asistencia','Notas de clase','Finalizar clase'],Admin:['Ingresos','Morosidad','Membresías','Alumnos','Retención','Prospectos'],Dueño:['MRR ₡0','Alumnos 0','Retención 0%','Churn 0%','Ocupación 0%','Morosidad ₡0']};return <div className="role-modes"><p className="kicker">EXPERIENCIA POR ROL</p><div className="mode-tabs">{Object.keys(modes).map(x=><button className={mode===x?'selected':''} onClick={()=>setMode(x)} key={x}>{mode==='Instructor'&&x==='Instructor'?'👨‍🏫 ':mode==='Admin'&&x==='Admin'?'📊 ':'👑 '}{x}</button>)}</div><div className="mode-preview"><p className="kicker">MODO {mode.toUpperCase()}</p>{modes[mode].map((x,i)=><div key={x}><strong>{x}</strong>{mode==='Instructor'&&i>0&&<button className="outline">Abrir</button>}</div>)}</div></div>}
function PlatformConfig(){const[type,setType]=useState('Artes marciales');const modules={ 'Artes marciales':'Cinturones · stripes · competencias · técnicas',Boxeo:'Niveles · peleas · categorías · condición',Danza:'Niveles · coreografías · presentaciones',Música:'Instrumentos · niveles · recitales',Idiomas:'Niveles · cursos · evaluaciones',Fitness:'Programas · metas · mediciones',Yoga:'Niveles · prácticas · bienestar',Arte:'Técnicas · proyectos · exposiciones',Educación:'Cursos · evaluaciones · certificados',Otra:'Módulos configurables'};return <div className="platform-config"><p className="kicker">IKIGAI · ACADEMY MANAGEMENT PLATFORM</p><h3>Configura tu vertical</h3><label>¿Qué tipo de academia tienes?<select value={type} onChange={e=>setType(e.target.value)}>{Object.keys(modules).map(x=><option key={x}>{x}</option>)}</select></label><div className="vertical-result"><strong>{type}</strong><span>{modules[type]}</span></div><div className="saas-checklist">{['Multi-tenant y multi-sucursal','Billing y suscripciones SaaS','Facturación electrónica y pagos online','Auditoría, backups y logs','Seguridad, 2FA, API y webhooks','White-label y dominios personalizados','PWA e integraciones'].map(x=><span key={x}>✓ {x}</span>)}</div></div>}
function Roles(){const[role,setRole]=useState('INSTRUCTOR');const permissions=['Ver alumnos','Asistencia','Progreso','Clases','Finanzas','Configuración','Reportes financieros'];const allowed=new Set(role==='INSTRUCTOR'?['Ver alumnos','Asistencia','Progreso','Clases']:role==='STUDENT'?['Progreso','Clases']:role==='PARENT'?['Progreso','Clases']:permissions);return <div className="roles-board"><div className="role-picker"><label>Rol seleccionado<select value={role} onChange={e=>setRole(e.target.value)}>{roles.map(x=><option key={x}>{x}</option>)}</select></label><span>{roles.length} roles disponibles</span></div><div className="role-list">{roles.map(x=><button key={x} className={role===x?'selected':''} onClick={()=>setRole(x)}>{x}</button>)}</div><div className="permission-table"><p className="kicker">PERMISOS GRANULARES · {role}</p>{permissions.map(x=><div key={x}><span>{allowed.has(x)?'✓':'✗'}</span><strong>{x}</strong><small>{allowed.has(x)?'Permitido':'Restringido'}</small></div>)}</div></div>}
function Settings(){const[branch,setBranch]=useState('Todas las sucursales');const branches=['Todas las sucursales','San José','Heredia','Escazú','Cartago'];return <><div className="module-heading"><div><p className="kicker">SISTEMA · CONFIGURACIÓN</p><h2>Configuración</h2><p>Define cómo funciona y se presenta tu academia.</p></div><button>Guardar cambios</button></div><section className="module-panel"><p className="kicker">MULTISUCURSAL</p><h3>IKIGAI Academy</h3><div className="branch-selector"><label>Sucursal activa<select value={branch} onChange={e=>setBranch(e.target.value)}>{branches.map(x=><option key={x}>{x}</option>)}</select></label><span>Vista actual: <strong>{branch}</strong></span></div><div className="branch-grid">{branches.slice(1).map(x=><div key={x}><strong>{x}</strong><small>Clases · alumnos · finanzas</small><button className="outline">Administrar sede</button></div>)}</div><div className="access-callout"><p className="kicker">ACCESOS</p><strong>Dueño: todas las sucursales</strong><span>Administrador de sede: únicamente su sucursal asignada</span></div><div className="roles-section"><p className="kicker">ROLES Y PERMISOS</p><h3>Accesos granulares</h3><Roles/></div><PlatformConfig/><AcademyConfig/><RoleModes/><IkigaiPlans/><SaaSBilling/><TasksAudit/><TenantSecurity/></section></>}
function Attendance(){const[active,setActive]=useState('today'),item=attendanceMenu.find(x=>x[0]===active);return <><div className="module-heading"><div><p className="kicker">MÓDULO 03 · ASISTENCIA</p><h2>Asistencia</h2><p>Registra la presencia y acompaña la constancia de tu comunidad.</p></div><button>Registrar asistencia</button></div><div className="classes-layout"><nav className="subnav">{attendanceMenu.map(([id,label,help])=><button key={id} className={active===id?'selected':''} onClick={()=>setActive(id)}><span>{label}</span><small>{help}</small></button>)}</nav><section className="module-panel"><p className="kicker">{item[1].toUpperCase()}</p><h3>{item[1]}</h3><div className="empty-state"><div className="empty-mark">✦</div><strong>{active==='today'?'Tu control diario empieza aquí':'Esta vista está lista para configurar'}</strong><p>La asistencia se asociará a cada clase, fecha y alumno, con historial y alertas reales.</p><button className="outline">Configurar {item[1].toLowerCase()}</button></div></section></div></>}
function LiveStudents(){const[rows,setRows]=useState([]),[show,setShow]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({full_name:'',email:'',phone:'',discipline:'',level:'Blanco',medical_notes:'',emergency_contact:''}),[error,setError]=useState('');const load=async()=>{const{data,error}=await supabase.from('students').select('*').order('created_at',{ascending:false});if(error)setError(error.message);else setRows(data||[])};useEffect(()=>{load()},[]);const save=async e=>{e.preventDefault();setError('');const payload={...form,active:true};const q=editing?supabase.from('students').update(payload).eq('id',editing):supabase.from('students').insert(payload);const{error}=await q;if(error)setError(error.message);else{setShow(false);setEditing(null);setForm({full_name:'',email:'',phone:'',discipline:'',level:'Blanco',medical_notes:'',emergency_contact:''});load()}};const remove=async id=>{if(!confirm('¿Eliminar este alumno definitivamente?'))return;const{error}=await supabase.from('students').delete().eq('id',id);if(error)setError(error.message);else load()};const toggle=async r=>{const{error}=await supabase.from('students').update({active:!r.active}).eq('id',r.id);if(error)setError(error.message);else load()};return <><div className="module-heading"><div><p className="kicker">MÓDULO 02 · ALUMNOS</p><h2>Alumnos</h2><p>Directorio conectado a Supabase.</p></div><button onClick={()=>{setEditing(null);setForm({full_name:'',email:'',phone:'',discipline:'',level:'Blanco',medical_notes:'',emergency_contact:''});setShow(true)}}>+ Nuevo alumno</button></div><section className="module-panel"><div className="section-title"><div><p className="kicker">DIRECTORIO</p><h3>{rows.length} alumnos</h3></div></div>{error&&<div className="error">{error}</div>}{rows.length?<div className="data-list">{rows.map(r=><article key={r.id}><div><strong>{r.full_name||'Sin nombre'}</strong><small>{r.discipline||'Sin disciplina'} · {r.level||'Sin nivel'} · {r.active===false?'Suspendido':'Activo'}</small><small>{r.email||'Sin correo'} · {r.phone||'Sin teléfono'}</small></div><div className="row-actions"><button className="outline" onClick={()=>{setEditing(r.id);setForm({...form,...r});setShow(true)}}>Editar</button><button className="outline" onClick={()=>toggle(r)}>{r.active===false?'Reactivar':'Suspender'}</button><button className="outline" onClick={()=>remove(r.id)}>Eliminar</button></div></article>)}</div>:<div className="empty-state"><div className="empty-mark">✦</div><strong>No hay alumnos registrados</strong><p>Agrega el primer alumno para comenzar.</p></div>}</section>{show&&<div className="modal-backdrop"><form className="modal-card" onSubmit={save}><div className="section-title"><h3>{editing?'Editar alumno':'Nuevo alumno'}</h3><button type="button" className="outline" onClick={()=>setShow(false)}>Cerrar</button></div><div className="form-grid"><label>Nombre completo<input required value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>Correo<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Teléfono<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Disciplina<input required value={form.discipline} onChange={e=>setForm({...form,discipline:e.target.value})}/></label><label>Nivel<select value={form.level} onChange={e=>setForm({...form,level:e.target.value})}><option>Blanco</option><option>Principiante</option><option>Intermedio</option><option>Avanzado</option></select></label><label>Contacto de emergencia<input value={form.emergency_contact} onChange={e=>setForm({...form,emergency_contact:e.target.value})}/></label><label className="full">Información médica<textarea value={form.medical_notes} onChange={e=>setForm({...form,medical_notes:e.target.value})}/></label></div>{error&&<div className="error">{error}</div>}<button type="submit">Guardar alumno</button></form></div>}</>}
function App(){const{session,loading,supabase}=useContext(AuthContext);const[hash,setHash]=useState(location.hash);const[role,setRole]=useState(null);useEffect(()=>{const onHash=()=>setHash(location.hash);addEventListener('hashchange',onHash);return()=>removeEventListener('hashchange',onHash)},[]);useEffect(()=>{if(session)supabase.from('profiles').select('role').eq('id',session.user.id).single().then(({data})=>setRole(data?.role||'student'));else setRole(null)},[session]);if(loading)return <main className="loading">Cargando Ikigai…</main>;if(!session)return <Login/>;const restricted=['#finanzas','#reportes','#configuracion'];if(role&&role!=='admin'&&restricted.includes(hash))return <main className="auth"><div className="auth-card"><img src="/ikigai-logo.png"/><p className="kicker">ACCESO RESTRINGIDO</p><h1>Esta sección requiere permisos de administrador.</h1><p>Tu rol actual es: {role}.</p><button onClick={()=>{location.hash='#inicio';setHash('#inicio')}}>Volver al inicio</button></div></main>;return <main className="app"><aside><img src="/ikigai-logo.png"/><span>IKIGAI</span><p className="aside-label">ACADEMIA</p><nav><a className={hash==='#alumnos'?'active':''} href="#alumnos">👥 Alumnos</a><a className={hash==='#asistencia'?'active':''} href="#asistencia">✅ Asistencia</a><a className={hash==='#membresias'?'active':''} href="#membresias">💳 Membresías</a><a className={hash==='#finanzas'?'active':''} href="#finanzas">💰 Finanzas</a><a className={hash==='#progreso'?'active':''} href="#progreso">📈 Progreso</a><a className={hash==='#comunicacion'?'active':''} href="#comunicacion">📣 Comunicación</a><a className={hash==='#tienda'?'active':''} href="#tienda">🛍️ Tienda</a><a className={hash==='#personal'?'active':''} href="#personal">👨‍🏫 Personal</a><a className={hash==='#reportes'?'active':''} href="#reportes">📊 Reportes</a><a className={hash==='#configuracion'?'active':''} href="#configuracion">⚙️ Configuración</a><a className={hash!=='#alumnos'&&hash!=='#asistencia'&&hash!=='#membresias'&&hash!=='#finanzas'&&hash!=='#progreso'&&hash!=='#comunicacion'&&hash!=='#tienda'&&hash!=='#personal'&&hash!=='#reportes'&&hash!=='#configuracion'?'active':''} href="#clases">🥋 Clases</a></nav><button className="ghost" onClick={()=>supabase.auth.signOut()}>Cerrar sesión</button></aside><section className="workspace"><header><div><p className="kicker">PANEL DE ACADEMIA</p><h1>Buenos días, Sensei</h1></div><span className="session">{session.user.email}</span></header>{hash==='#alumnos'?<Students/>:hash==='#asistencia'?<Attendance/>:hash==='#membresias'?<Memberships/>:hash==='#finanzas'?<Finance/>:hash==='#progreso'?<Progress/>:hash==='#comunicacion'?<Communication/>:hash==='#tienda'?<Store/>:hash==='#personal'?<Staff/>:hash==='#reportes'?<Reports/>:hash==='#configuracion'?<Settings/>:hash==='#inicio'||hash===''?<Dashboard/>:<Classes/>}</section></main>}
Students=LiveStudentsV2;
Memberships=LiveMemberships; Classes=LiveClasses; Attendance=LiveAttendanceV2; Finance=LiveFinance; Reports=LiveReports; TasksAudit=LiveAudit; Communication=LiveCommunicationV2;
createRoot(document.getElementById('root')).render(<AuthProvider><App/></AuthProvider>);
function LiveReports(){const[data,setData]=useState({students:0,paid:0,pending:0,expenses:0});const load=async()=>{const[s,p,e]=await Promise.all([supabase.from('students').select('id',{count:'exact',head:true}),supabase.from('payments').select('amount,status'),supabase.from('expenses').select('amount')]);setData({students:s.count||0,paid:(p.data||[]).filter(x=>x.status==='paid').reduce((a,x)=>a+Number(x.amount||0),0),pending:(p.data||[]).filter(x=>x.status!=='paid').reduce((a,x)=>a+Number(x.amount||0),0),expenses:(e.data||[]).reduce((a,x)=>a+Number(x.amount||0),0)})};useEffect(()=>{load();const channel=supabase.channel('live-reports').on('postgres_changes',{event:'*',schema:'public',table:'students'},load).on('postgres_changes',{event:'*',schema:'public',table:'payments'},load).on('postgres_changes',{event:'*',schema:'public',table:'expenses'},load).subscribe();return()=>{supabase.removeChannel(channel)}},[]);return <><div className="module-heading"><div><p className="kicker">DATOS REALES · SUPABASE</p><h2>Reportes</h2><p>Indicadores calculados desde pagos, gastos y alumnos.</p></div></div><section className="module-panel"><div className="report-metrics"><div><strong>{data.students}</strong><span>Alumnos</span></div><div><strong>₡{data.paid.toLocaleString('es-CR')}</strong><span>Ingresos pagados</span></div><div><strong>₡{data.pending.toLocaleString('es-CR')}</strong><span>Pendiente</span></div><div><strong>₡{data.expenses.toLocaleString('es-CR')}</strong><span>Gastos</span></div><div><strong>₡{(data.paid-data.expenses).toLocaleString('es-CR')}</strong><span>Balance</span></div></div><div className="report-chart"><strong>Resumen financiero real</strong><p>Se actualiza automáticamente con cambios de Supabase.</p></div></section></>}
function LiveAudit(){const[rows,setRows]=useState([]),[error,setError]=useState('');useEffect(()=>{supabase.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(100).then(r=>{if(r.error)setError('La tabla audit_logs aún no está creada en Supabase.');else setRows(r.data||[])})},[]);return <section className="module-panel"><p className="kicker">TRAZABILIDAD</p><h3>Auditoría administrativa</h3>{error?<div className="error">{error}</div>:rows.length?rows.map(r=><article className="data-row" key={r.id}><strong>{r.action}</strong><span>{r.entity_type} · {r.created_at}</span></article>):<div className="empty-state"><strong>No hay acciones registradas</strong><p>Las acciones administrativas aparecerán aquí.</p></div>}</section>}
function LiveStudentsV2(){const empty={full_name:'',email:'',phone:'',discipline:'',level:'Blanco',medical_notes:'',emergency_contact:'',membership_id:'',membership_expires_at:''};const[rows,setRows]=useState([]),[plans,setPlans]=useState([]),[form,setForm]=useState(empty),[edit,setEdit]=useState(null),[open,setOpen]=useState(false),[error,setError]=useState('');const load=async()=>{const[a,b]=await Promise.all([supabase.from('students').select('*,memberships(name,amount)').order('created_at',{ascending:false}),supabase.from('memberships').select('id,name,amount').eq('active',true).order('name')]);if(a.error)setError(a.error.message);else setRows(a.data||[]);if(!b.error)setPlans(b.data||[])};useEffect(()=>{load()},[]);const save=async e=>{e.preventDefault();setError('');const payload={...form,active:true,membership_id:form.membership_id||null,membership_status:form.membership_expires_at?(form.membership_expires_at>=new Date().toISOString().slice(0,10)?'active':'expired'):'pending'};const r=edit?await supabase.from('students').update(payload).eq('id',edit):await supabase.from('students').insert(payload);if(r.error)setError(r.error.message);else{await audit(edit?'update':'create','students',edit||null,payload);setOpen(false);setEdit(null);setForm(empty);load()}};return <><div className="module-heading"><div><p className="kicker">MÓDULO 02 · ALUMNOS</p><h2>Alumnos</h2><p>Directorio, información médica y membresía asignada.</p></div><button onClick={()=>{setForm(empty);setEdit(null);setOpen(true)}}>+ Nuevo alumno</button></div><section className="module-panel">{error&&<div className="error">{error}</div>}{rows.length?<div className="data-list">{rows.map(r=><article key={r.id}><div><strong>{r.full_name||'Sin nombre'}</strong><small>{r.discipline||'Sin disciplina'} · {r.active===false?'Suspendido':'Activo'}</small><small>{r.memberships?.name||'Sin membresía'} · vence {r.membership_expires_at||'sin fecha'}</small></div><div className="row-actions"><button className="outline" onClick={()=>{setForm({...empty,...r});setEdit(r.id);setOpen(true)}}>Editar</button><button className="outline" onClick={async()=>{const q=await supabase.from('students').update({active:r.active===false}).eq('id',r.id);if(q.error)setError(q.error.message);else{await audit(r.active===false?'reactivate':'suspend','students',r.id);load()}}}>{r.active===false?'Reactivar':'Suspender'}</button><button className="outline" onClick={async()=>{if(confirm('¿Eliminar este alumno definitivamente?')){const q=await supabase.from('students').delete().eq('id',r.id);if(q.error)setError(q.error.message);else{await audit('delete','students',r.id);load()}}}}>Eliminar</button></div></article>)}</div>:<div className="empty-state"><strong>No hay alumnos registrados</strong><p>Agrega el primer alumno para comenzar.</p></div>}</section>{open&&<div className="modal-backdrop"><form className="modal-card" onSubmit={save}><h3>{edit?'Editar alumno':'Nuevo alumno'}</h3><div className="form-grid"><label>Nombre completo<input required value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>Correo<input type="email" value={form.email||''} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Teléfono<input value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Disciplina<input required value={form.discipline||''} onChange={e=>setForm({...form,discipline:e.target.value})}/></label><label>Nivel<select value={form.level||'Blanco'} onChange={e=>setForm({...form,level:e.target.value})}><option>Blanco</option><option>Principiante</option><option>Intermedio</option><option>Avanzado</option></select></label><label>Membresía<select value={form.membership_id||''} onChange={e=>setForm({...form,membership_id:e.target.value})}><option value="">Sin membresía</option>{plans.map(p=><option value={p.id} key={p.id}>{p.name} · ₡{Number(p.amount).toLocaleString('es-CR')}</option>)}</select></label><label>Vencimiento<input type="date" value={form.membership_expires_at||''} onChange={e=>setForm({...form,membership_expires_at:e.target.value})}/></label><label>Emergencia<input value={form.emergency_contact||''} onChange={e=>setForm({...form,emergency_contact:e.target.value})}/></label><label className="full">Información médica<textarea value={form.medical_notes||''} onChange={e=>setForm({...form,medical_notes:e.target.value})}/></label></div>{error&&<div className="error">{error}</div>}<button>Guardar alumno</button><button type="button" className="outline" onClick={()=>setOpen(false)}>Cerrar</button></form></div>}</>}
function LiveCommunicationV2(){const[tab,setTab]=useState('gallery');return <><div className="module-heading"><div><p className="kicker">COMUNICACIÓN · SUPABASE</p><h2>Comunicación</h2><p>Noticias, galería y notificaciones persistentes.</p></div></div><div className="report-tabs"><button className={tab==='gallery'?'selected':''} onClick={()=>setTab('gallery')}>Galería</button><button className={tab==='news'?'selected':''} onClick={()=>setTab('news')}>Noticias</button><button className={tab==='notify'?'selected':''} onClick={()=>setTab('notify')}>Notificar</button></div>{tab==='gallery'?<LiveCommunication/>:tab==='news'?<LiveTable title="Noticias" table="news" fields={[['title','Título'],['body','Contenido'],['published','Publicada','checkbox']]}/>:<section className="module-panel"><p className="kicker">NOTIFICACIÓN</p><h3>Enviar correo</h3><p>La solicitud se guarda primero en Supabase y luego intenta entregarse por Edge Function.</p><label>Correo<input id="notification-to" type="email" required/></label><label>Mensaje<textarea id="notification-message" required/></label><button onClick={async()=>{const to=document.getElementById('notification-to').value;const message=document.getElementById('notification-message').value;const saved=await supabase.from('notifications').insert({channel:'email',recipient:to,subject:'Mensaje de Ikigai',message,status:'queued'}).select().single();if(saved.error){alert(saved.error.message);return}const sent=await supabase.functions.invoke('send-notification',{body:{channel:'email',to,subject:'Mensaje de Ikigai',message}});await supabase.from('notifications').update({status:sent.error?'failed':'sent',provider_response:sent.error||sent.data,sent_at:sent.error?null:new Date().toISOString()}).eq('id',saved.data.id);alert(sent.error?'Guardado en cola; proveedor pendiente.':'Notificación enviada')}}>Guardar y enviar correo</button></section>}</>}
function LiveCommunication(){const[tab,setTab]=useState('gallery'),[items,setItems]=useState([]),[file,setFile]=useState(null),[message,setMessage]=useState(''),[to,setTo]=useState(''),[error,setError]=useState(''),[status,setStatus]=useState('');const load=async()=>{const r=await supabase.from('gallery').select('*').order('created_at',{ascending:false});if(r.error)setError(r.error.message);else setItems(r.data||[])};useEffect(()=>{load()},[]);const upload=async()=>{if(!file)return;setError('');setStatus('');const path=crypto.randomUUID()+'-'+file.name.toLowerCase().replace(/[^a-z0-9.-]/g,'-');const up=await supabase.storage.from('ikigai-gallery').upload(path,file,{contentType:file.type});if(up.error){setError(up.error.message);return}const url=supabase.storage.from('ikigai-gallery').getPublicUrl(path).data.publicUrl;const row=await supabase.from('gallery').insert({image_url:url,caption:file.name}).select().single();if(row.error){setError(row.error.message);return}setFile(null);setStatus('Imagen subida');load()};const remove=async item=>{if(!confirm('¿Eliminar esta imagen?'))return;const path=item.image_url.split('/ikigai-gallery/')[1];await supabase.from('gallery').delete().eq('id',item.id);if(path)await supabase.storage.from('ikigai-gallery').remove([path]);load()};const send=async()=>{setError('');setStatus('');const r=await supabase.functions.invoke('send-notification',{body:{channel:'email',to,subject:'Mensaje de Ikigai',message}});if(r.error)setError(r.error.message);else setStatus('Notificación enviada')};return <><div className="module-heading"><div><p className="kicker">COMUNICACIÓN · SUPABASE</p><h2>Galería y notificaciones</h2><p>Archivos y mensajes gestionados desde servicios reales.</p></div></div><div className="report-tabs"><button className={tab==='gallery'?'selected':''} onClick={()=>setTab('gallery')}>Galería</button><button className={tab==='notify'?'selected':''} onClick={()=>setTab('notify')}>Notificar</button></div>{tab==='gallery'?<section className="module-panel"><label>Imagen<input type="file" accept="image/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><button onClick={upload} disabled={!file}>Subir imagen</button>{status&&<div className="success">{status}</div>}{error&&<div className="error">{error}</div>}<div className="gallery-grid">{items.length?items.map(x=><article key={x.id}><img src={x.image_url} alt={x.caption||'Galería Ikigai'}/><small>{x.caption}</small><button className="outline" onClick={()=>remove(x)}>Eliminar</button></article>):<div className="empty-state"><strong>Galería vacía</strong><p>Sube la primera imagen.</p></div>}</div></section>:<section className="module-panel"><label>Correo<input type="email" value={to} onChange={e=>setTo(e.target.value)} required/></label><label>Mensaje<textarea value={message} onChange={e=>setMessage(e.target.value)} required/></label><button onClick={send}>Enviar correo</button>{status&&<div className="success">{status}</div>}{error&&<div className="error">{error}</div>}</section>}</>}
function LiveFinance(){const[tab,setTab]=useState('payments');return <><div className="module-heading"><div><p className="kicker">SUPABASE · FINANZAS</p><h2>Finanzas</h2><p>Ingresos y gastos reales de Ikigai.</p></div></div><div className="report-tabs"><button className={tab==='payments'?'selected':''} onClick={()=>setTab('payments')}>Pagos</button><button className={tab==='expenses'?'selected':''} onClick={()=>setTab('expenses')}>Gastos</button></div>{tab==='payments'?<LivePaymentsV2/>:<LiveTable title="Gastos" table="expenses" fields={[['concept','Concepto'],['amount','Monto','number'],['category','Categoría'],['expense_date','Fecha','date']]}/>}</>}

function LiveTable({title,table,fields}){const[rows,setRows]=useState([]),[open,setOpen]=useState(false),[edit,setEdit]=useState(null),[form,setForm]=useState({}),[error,setError]=useState('');const load=async()=>{const r=await supabase.from(table).select('*').order('created_at',{ascending:false});if(r.error)setError(r.error.message);else setRows(r.data||[])};useEffect(()=>{load();const channel=supabase.channel('live-'+table).on('postgres_changes',{event:'*',schema:'public',table},load).subscribe();return()=>{supabase.removeChannel(channel)}},[table]);const save=async e=>{e.preventDefault();setError('');const clean=Object.fromEntries(fields.map(([k,,type])=>[k,type==='checkbox'?Boolean(form[k]):form[k]]));const r=edit?await supabase.from(table).update(clean).eq('id',edit):await supabase.from(table).insert(clean);if(r.error)setError(r.error.message);else{await audit(edit?'update':'create',table,edit||null,clean);setOpen(false);setEdit(null);load()}};return <><div className="module-heading"><div><p className="kicker">SUPABASE · {table.toUpperCase()}</p><h2>{title}</h2><p>Datos reales sincronizados en vivo.</p></div><button onClick={()=>{setForm({});setEdit(null);setOpen(true)}}>+ Nuevo registro</button></div><section className="module-panel">{error&&<div className="error">{error}</div>}{rows.length?rows.map(r=><article className="data-row" key={r.id}><strong>{r.name||r.full_name||r.concept||r.class_date||'Registro'}</strong><span>{r.amount||r.discipline||r.start_time||r.expense_date||''}</span><button className="outline" onClick={()=>{setEdit(r.id);setForm(Object.fromEntries(fields.map(([k,,type])=>[k,r[k]??(type==='checkbox'?false:'')] )));setOpen(true)}}>Editar</button><button className="outline" onClick={async()=>{if(confirm('¿Eliminar este registro?')){const q=await supabase.from(table).delete().eq('id',r.id);if(q.error)setError(q.error.message);else{await audit('delete',table,r.id);load()}}}}>Eliminar</button></article>):<div className="empty-state"><div className="empty-mark">✦</div><strong>No hay registros</strong><p>Agrega el primero desde este módulo.</p></div>}</section>{open&&<div className="modal-backdrop"><form className="modal-card" onSubmit={save}><h3>{edit?'Editar':'Nuevo'} {title}</h3>{fields.map(([key,label,type='text'])=><label key={key}>{label}<input required={['name','full_name','concept','discipline','class_date','amount'].includes(key)} type={type==='checkbox'?'checkbox':type} checked={type==='checkbox'?Boolean(form[key]):undefined} value={type==='checkbox'?undefined:(form[key]||'')} onChange={e=>setForm({...form,[key]:type==='checkbox'?e.target.checked:e.target.value})}/></label>)}{error&&<div className="error">{error}</div>}<button>Guardar</button><button type="button" className="outline" onClick={()=>setOpen(false)}>Cerrar</button></form></div>}</>}
