function LivePaymentsV2(){const[students,setStudents]=useState([]),[rows,setRows]=useState([]),[open,setOpen]=useState(false),[error,setError]=useState(''),[form,setForm]=useState({student_id:'',amount:'',period:'',status:'paid',payment_method:'cash',paid_at:new Date().toISOString().slice(0,16)});const load=async()=>{const[a,b]=await Promise.all([supabase.from('students').select('id,full_name').order('full_name'),supabase.from('payments').select('*,students(full_name)').order('created_at',{ascending:false})]);if(a.error||b.error)setError((a.error||b.error).message);else{setStudents(a.data||[]);setRows(b.data||[])}};useEffect(()=>{load();const ch=supabase.channel('live-payments').on('postgres_changes',{event:'*',schema:'public',table:'payments'},load).subscribe();return()=>supabase.removeChannel(ch)},[]);const save=async e=>{e.preventDefault();const payload={...form,amount:Number(form.amount),paid_at:form.status==='paid'?new Date(form.paid_at).toISOString():null};const r=await supabase.from('payments').insert(payload).select().single();if(r.error)setError(r.error.message);else{await audit('create','payments',r.data.id,payload);setOpen(false);setForm({...form,student_id:'',amount:'',period:''});load()}};const remove=async id=>{if(!confirm('¿Eliminar este pago?'))return;const r=await supabase.from('payments').delete().eq('id',id);if(r.error)setError(r.error.message);else{await audit('delete','payments',id);load()}};const markPaid=async r=>{const q=await supabase.from('payments').update({status:'paid',paid_at:new Date().toISOString()}).eq('id',r.id);if(q.error)setError(q.error.message);else{await audit('update','payments',r.id,{status:'paid'});load()}};return <><div className="module-heading"><div><p className="kicker">SUPABASE · PAYMENTS</p><h2>Pagos</h2><p>Registra cobros con alumno y método de pago.</p></div><button onClick={()=>setOpen(true)}>+ Registrar pago</button></div><section className="module-panel">{error&&<div className="error">{error}</div>}{rows.length?rows.map(r=><article className="data-row" key={r.id}><strong>{r.students?.full_name||'Alumno'}</strong><span>₡{Number(r.amount).toLocaleString('es-CR')} · {r.payment_method||'cash'} · {r.status}</span><button className="outline" onClick={()=>printReceipt(r)}>Recibo PDF</button>{r.status!=='paid'&&<button className="outline" onClick={()=>markPaid(r)}>Marcar pagado</button>}<button className="outline" onClick={()=>remove(r.id)}>Eliminar</button></article>):<div className="empty-state"><strong>No hay pagos registrados</strong><p>Registra el primer cobro.</p></div>}</section>{open&&<div className="modal-backdrop"><form className="modal-card" onSubmit={save}><h3>Registrar pago</h3><label>Alumno<select required value={form.student_id} onChange={e=>setForm({...form,student_id:e.target.value})}><option value="">Seleccionar alumno</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></label><label>Monto<input required type="number" min="0" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Periodo<input required value={form.period} placeholder="Septiembre 2026" onChange={e=>setForm({...form,period:e.target.value})}/></label><label>Método<select value={form.payment_method} onChange={e=>setForm({...form,payment_method:e.target.value})}><option value="cash">Efectivo</option><option value="sinpe">SINPE</option><option value="transfer">Transferencia</option><option value="card">Tarjeta</option></select></label><label>Estado<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="paid">Pagado</option><option value="pending">Pendiente</option></select></label><label>Fecha<input type="datetime-local" value={form.paid_at} onChange={e=>setForm({...form,paid_at:e.target.value})}/></label><button>Guardar pago</button><button type="button" className="outline" onClick={()=>setOpen(false)}>Cerrar</button></form></div>}</>}
function LiveAttendanceV2(){const[classes,setClasses]=useState([]),[students,setStudents]=useState([]),[form,setForm]=useState({class_id:'',student_id:'',marked_at:new Date().toISOString().slice(0,16),present:true}),[rows,setRows]=useState([]),[error,setError]=useState('');const load=async()=>{const[a,b,c]=await Promise.all([supabase.from('classes').select('id,name,class_date,start_time').order('class_date'),supabase.from('students').select('id,full_name').eq('active',true).order('full_name'),supabase.from('attendance').select('*,classes(name),students(full_name)').order('marked_at',{ascending:false}).limit(100)]);if(a.error||b.error||c.error)setError((a.error||b.error||c.error).message);else{setClasses(a.data||[]);setStudents(b.data||[]);setRows(c.data||[])}};useEffect(()=>{load();const ch=supabase.channel('live-attendance').on('postgres_changes',{event:'*',schema:'public',table:'attendance'},load).subscribe();return()=>supabase.removeChannel(ch)},[]);const save=async e=>{e.preventDefault();setError('');const r=await supabase.from('attendance').upsert(form,{onConflict:'class_id,student_id'});if(r.error)setError(r.error.message);else{await audit('attendance','attendance',null,form);setForm({...form,present:true});load()}};return <><div className="module-heading"><div><p className="kicker">MÓDULO 03 · ASISTENCIA</p><h2>Registrar asistencia</h2><p>Clase, alumno y fecha guardados en Supabase.</p></div></div><section className="module-panel"><form className="form-grid" onSubmit={save}><label>Clase<select required value={form.class_id} onChange={e=>setForm({...form,class_id:e.target.value})}><option value="">Seleccionar clase</option>{classes.map(c=><option key={c.id} value={c.id}>{c.name} · {c.class_date} {c.start_time?.slice(0,5)}</option>)}</select></label><label>Alumno<select required value={form.student_id} onChange={e=>setForm({...form,student_id:e.target.value})}><option value="">Seleccionar alumno</option>{students.map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></label><label>Fecha y hora<input required type="datetime-local" value={form.marked_at} onChange={e=>setForm({...form,marked_at:e.target.value})}/></label><label>Estado<select value={form.present?'true':'false'} onChange={e=>setForm({...form,present:e.target.value==='true'})}><option value="true">Presente</option><option value="false">Ausente</option></select></label><button>Guardar asistencia</button></form>{error&&<div className="error">{error}</div>}<h3>Historial reciente</h3>{rows.length?rows.map(r=><article className="data-row" key={r.id}><strong>{r.students?.full_name||'Alumno'}</strong><span>{r.classes?.name||'Clase'} · {r.present?'Presente':'Ausente'} · {new Date(r.marked_at).toLocaleString('es-CR')}</span></article>):<div className="empty-state"><strong>No hay asistencias registradas</strong><p>El historial aparecerá aquí.</p></div>}</section></>}
